    {
      "title": "Card placeholder",
      "code": "<div className=\"space-y-2\">\n  <Skeleton className=\"h-24 w-full rounded-lg\" />\n  <Skeleton className=\"h-4 w-2/3\" />\n</div>",
      "description": "Placeholder matching a card layout"
    },
    {
      "title": "With live-region announcement",
      "code": "<span role=\"status\" className=\"sr-only\">Loading…</span>\n<Skeleton className=\"h-4 w-48\" />",
      "description": "Announcing the loading state to screen readers"
    }
  ],
