      "userRequirements": "Provide a separate status region that announces loading"
    },
    {
      "feature": "Reduced motion",
      "implementation": "Pulse animation is disabled under prefers-reduced-motion",
      "userRequirements": "Don't re-enable animations via CSS overrides"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Shapes",
