      "relationship": "Always pair with a status region to announce loading",
      "example": "<span role=\"status\" className=\"sr-only\">Loading…</span><Skeleton className=\"h-4 w-32\" />"
    }
  ],
  "relatedComponents": ["Progress", "Spinner"],
  "package": "@slipstream-ui/core",
